package com.logiplatform.service;
import com.logiplatform.dto.OperationsDtos.*; import com.logiplatform.model.*; import com.logiplatform.repository.*; import com.logiplatform.tenancy.TenantContext; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.util.*;
@Service public class CarrierTenderService { private final CarrierTenderRepository repo; private final ShipmentRepository shipments; private final NotificationService notifications; public CarrierTenderService(CarrierTenderRepository r,ShipmentRepository s,NotificationService n){repo=r;shipments=s;notifications=n;}
 @Transactional public TenderResponse send(TenderRequest r){UUID t=TenantContext.getTenantId(); if(repo.findByTenantIdAndTenderKey(t,r.tenderKey()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Tender key already exists"); if(r.shipmentId()!=null){Shipment s=shipments.findByIdAndTenantId(r.shipmentId(),t).orElseThrow(()->nf("Shipment not found"));notifications.notify(s.getId(),s.getNotificationEmail(),"Carrier tender sent: "+s.getReferenceCode(),"Carrier "+r.carrierName()+" has been invited to tender transport.");} return TenderResponse.from(repo.save(new CarrierTender(t,r.shipmentId(),r.tripId(),r.tenderKey(),r.carrierName(),r.carrierContact(),r.quotedAmount(),r.currency(),r.expiresAt(),r.note())));}
 @Transactional(readOnly=true) public List<TenderResponse> list(){return repo.findAllByTenantIdOrderByCreatedAtDesc(TenantContext.getTenantId()).stream().map(TenderResponse::from).toList();}
 @Transactional public TenderResponse accept(UUID id,String note){CarrierTender x=owned(id);x.accept(note);return TenderResponse.from(repo.save(x));} @Transactional public TenderResponse reject(UUID id,String note){CarrierTender x=owned(id);x.reject(note);return TenderResponse.from(repo.save(x));}
 private CarrierTender owned(UUID id){return repo.findByIdAndTenantId(id,TenantContext.getTenantId()).orElseThrow(()->nf("Tender not found"));} private static ResponseStatusException nf(String m){return new ResponseStatusException(HttpStatus.NOT_FOUND,m);} }
